<?php
$reservations = ClientApi::data($api->request('GET', 'api/reservations'));
$reservations = is_array($reservations) ? $reservations : [];
$notifs = ClientApi::data($api->request('GET', 'api/notifications?page=1&per_page=5'));
$notifications = is_array($notifs['items'] ?? null) ? $notifs['items'] : [];
$active = count(array_filter($reservations, static fn($r) => in_array($r['statut'] ?? '', ['demande','confirmee'], true)));
$unread = count(array_filter($notifications, static fn($n) => empty($n['lu_at'])));
?>
<section class="grid stats"><article class="card"><div class="stat-label">Réservations actives</div><div class="stat-value"><?= $active ?></div><div class="stat-foot">Demandes et voyages confirmés</div></article><article class="card"><div class="stat-label">Destinations favorites</div><div class="stat-value"><a href="?page=favorites">Voir →</a></div><div class="stat-foot">Vos lieux à découvrir</div></article><article class="card"><div class="stat-label">Notifications non lues</div><div class="stat-value"><?= $unread ?></div><div class="stat-foot">Restez informé de vos voyages</div></article><article class="card"><div class="stat-label">Membre depuis</div><div class="stat-value" style="font-size:20px"><?= client_h(isset($user['created_at']) ? date('m/Y', strtotime($user['created_at'])) : '—') ?></div><div class="stat-foot">Bienvenue chez Tourisme Ivoire</div></article></section>
<section class="grid two-col"><article class="panel"><h2 class="section-title">Réservations récentes <a class="text-link" href="?page=reservations">Tout voir →</a></h2><?php if (!$reservations): ?><div class="empty"><div class="empty-icon">✦</div><h3>Votre prochain voyage vous attend</h3><p>Vos demandes de transport apparaîtront ici après réservation.</p><a class="btn" href="?page=help">Découvrir comment réserver</a></div><?php else: ?><div class="list"><?php foreach (array_slice($reservations,0,5) as $r): ?><a class="list-row" href="?page=reservations&amp;id=<?= (int)$r['id'] ?>"><div><div class="row-title"><?= client_h($r['libelle_snapshot'] ?? $r['reference'] ?? 'Réservation') ?></div><div class="row-meta"><?= client_h($r['reference'] ?? '') ?> · <?= client_format_date($r['created_at'] ?? null) ?></div></div><?= client_status_badge((string)($r['statut'] ?? 'demande')) ?></a><?php endforeach; ?></div><?php endif; ?></article><article class="panel"><h2 class="section-title">Notifications <a class="text-link" href="?page=notifications">Voir tout →</a></h2><?php if (!$notifications): ?><div class="empty"><div class="empty-icon">♧</div><h3>Tout est calme</h3><p>Les mises à jour importantes apparaîtront ici.</p></div><?php else: ?><div class="list"><?php foreach (array_slice($notifications,0,4) as $n): ?><div class="list-row"><div><div class="row-title"><?= client_h($n['titre'] ?? '') ?></div><div class="row-meta"><?= client_h($n['contenu'] ?? '') ?></div></div><?php if (empty($n['lu_at'])): ?><span class="badge pending">Nouveau</span><?php endif; ?></div><?php endforeach; ?></div><?php endif; ?></article></section>
